import { Block, useAnimateParallel } from "@prototyp/skeletor";
import { type FC, useEffect } from "react";
import { Easing, Image, StyleSheet } from "react-native";
import { Button } from "shared/components";

interface Props {
  visible: boolean;
  onPress: () => void;
}

export const ScrollToBottomButton: FC<Props> = ({ visible, onPress }) => {
  const button = useAnimateParallel(
    {
      opacity: [0, 1],
      translateY: [16, 0],
    },
    {
      duration: 200,
      easing: Easing.ease,
    },
  );

  useEffect(() => {
    if (visible) button.start();
    else button.reverse();
  }, [visible]);

  return (
    <Block
      absolute
      offsets={{ right: 20, bottom: 100 }}
      align="center"
      justify="center"
      pointerEvents={visible ? "auto" : "none"}
      animations={button.animations}
    >
      <Button.Outline onPress={onPress} style={styles.button}>
        <Image source={require("assets/icons/arrow-down.png")} />
      </Button.Outline>
    </Block>
  );
};

const styles = StyleSheet.create({
  button: {
    width: 48,
    height: 48,
    borderRadius: 999,
  },
});

