import type { PropsWithChildren } from "react";
import { Animated, Easing, useEffect, useRef, View } from "react-native";
import { IpadSidebar } from "../ipad-sidebar";

const SIDEBAR_WIDTH = 440;

interface Props extends PropsWithChildren {
  showSidebar: boolean;
}

export const IpadLayoutWrapper: React.FC<Props> = ({
  children,
  showSidebar,
}) => {
  const marginLeft = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    if (showSidebar) {
      Animated.timing(marginLeft, {
        toValue: SIDEBAR_WIDTH,
        duration: 350,
        easing: Easing.out(Easing.cubic),
        useNativeDriver: false,
      }).start();
    }
  }, [showSidebar]);

  return (
    <View style={{ flex: 1 }}>
      <Animated.View style={{ flex: 1, marginLeft }}>{children}</Animated.View>
      {showSidebar && <IpadSidebar />}
    </View>
  );
};

