      .finally(() => setCheckingVerification(false));

    UserService.isUserBlocked(userId)
      .then(setIsUserBlocked)
      .catch(console.error);
  }, [userId, isFocused]);

  if (loading || !userProfile) return <Loading />;

  return (
    <ScreenLayout>
      <Block flex={1} gap={40} scrollable>
        {isLoading && (
          <Loading
            text={isUserBlocked ? "Unblocking user..." : "Blocking user..."}
          />
        )}
        <GoBackHeader margins={{ marginBottom: 40 }} />
        <Block align="center" gap={12}>
          <UserImage
            avatarUrl={userProfile?.avatarUrl}
            displayName={userProfile?.displayName}
            width={120}
            height={120}
            borderRadius={999}
            onPress={(uri) => setImageViewerPayload({ uri })}
          />
          <Block flexDirection="row" align="center" gap={8}>
            <Text size={TextSize.large} font="InstrumentSans-Bold">
              {userProfile?.displayName}
            </Text>
          </Block>
          <Text color={Colors.white50}>{userProfile?.userId}</Text>
          {!checkingVerification && isVerified && (
            <Block
              flexDirection="row"
              gap={4}
              align="center"
              justify="center"
              paddings={[6, 8]}
              border={{
                borderRadius: 8,
                borderWidth: 1,
                borderColor: Colors.primary,
              }}
            >
              <Image
                source={require("assets/icons/shield-check.png")}
                tintColor={Colors.primary}
                width={16}
                height={16}
                style={styles.verifiedIcon}
              />
              <Text size={TextSize.small} color={Colors.primary}>
                Verified by you
              </Text>
            </Block>
          )}
        </Block>
        <ActionButtons userProfile={userProfile} />
        <Block background={Colors.white5} border={{ borderRadius: 16 }}>
          {!isVerified && (
            <Button.Wrapper
              onPress={() => {
                NavigationContainerRef.navigate("verifyUser", { userId });
              }}
            >
              <Block paddings={[0, 12]}>
                <Block
                  flexDirection="row"
                  align="center"
                  gap={12}
                  paddings={[20, 0]}
                >
                  <Image
                    source={require("assets/icons/lock.png")}
                    tintColor={Colors.white50}
                    width={24}
                    height={24}
                    style={styles.icon}
                  />

                  <Text color={Colors.white}>Verify user</Text>
                </Block>
              </Block>
            </Button.Wrapper>
          )}
          <Button.Wrapper onPress={() => setIsBlockUserModalOpen(true)}>
            <Block paddings={[0, 12]}>
              <Block
                flexDirection="row"
                align="center"
                gap={12}
                paddings={[20, 0]}
              >
                <Image
                  source={require("assets/icons/ban.png")}
                  tintColor={Colors.white50}
                  width={24}
                  height={24}
                  style={styles.icon}
                />

                <Text color={Colors.white}>
                  {isUserBlocked ? "Unblock user" : "Block user"}
                </Text>
              </Block>
            </Block>
          </Button.Wrapper>
        </Block>
        <BlockUserModal
          visible={isBlockUserModalOpen}
          onCancel={() => setIsBlockUserModalOpen(false)}
          onConfirm={handleConfirmBlockUser}
          isLoading={isLoading}
          isUserBlocked={isUserBlocked}
        />
      </Block>
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  icon: {
    width: 24,
    height: 24,
  },
  verifiedIcon: {
    width: 16,
    height: 16,
  },
});
import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { useAtomValue, useSetAtom } from "jotai";
import { StorageAtoms } from "modules/storage/jotai/atoms";
import { TimelineAtoms } from "modules/timeline/jotai/atoms";
import { UserService } from "modules/user/service/UserService";
import { useState } from "react";
import { ActivityIndicator, Image, Modal, StyleSheet } from "react-native";
import type { Asset } from "react-native-image-picker";
import Toast from "react-native-toast-message";
import { SingleSendItem } from "screens/room/fragments/single-send-item";
import {
  Button,
  GoBackHeader,
  Input,
  Loading,
  ScreenLayout,
  UserImage,
} from "shared/components";
import { useUploadPhoto } from "shared/hooks";
import { Colors, TextSize } from "shared/styles";
import { offlineToastHelper } from "shared/utils";

export const UserProfile: React.FC<
  NativeStackScreenProps<Routes, "userProfile">
> = () => {
  const user = useAtomValue(StorageAtoms.cachedProfile);
  const [userImageUri, setUserImageUri] = useState<string | undefined>(
    user?.avatarUrl,
  );
  const {
    isLoading,
    selectedAsset,
    isListOpen,
    setSelectedAsset,
    setIsListOpen,
    handleChoosePhoto,
    handleTakePhoto,
  } = useUploadPhoto();
  const [displayName, setDisplayName] = useState<string | undefined>(
    user?.displayName,
  );
  const [isSaving, setIsSaving] = useState(false);
  const [shouldRemoveAvatar, setShouldRemoveAvatar] = useState(false);
  const setImageViewerPayload = useSetAtom(TimelineAtoms.imageViewerPayload);

  const handleRemove = () => {
    setUserImageUri(undefined);
    setSelectedAsset(null);
    setShouldRemoveAvatar(true);
  };

  const handleSave = async () => {
    try {
      setIsSaving(true);

      let avatarToUpload: Asset | null | undefined;

      if (shouldRemoveAvatar) {
        avatarToUpload = null; // User wants to remove avatar
      } else if (selectedAsset) avatarToUpload = selectedAsset;

      const updated = await UserService.updateProfile(
        displayName,
        avatarToUpload,
      );

      setShouldRemoveAvatar(false);
      setSelectedAsset(null);

      // The user state will be automatically updated via the atom
      setUserImageUri(updated?.avatarUrl);
      setDisplayName(updated?.displayName);

      Toast.show({
        type: "success",
        text1: "Profile updated successfully",
      });
    } catch (error) {
      console.error("Failed to update profile:", error);
      offlineToastHelper("Failed to update profile. Please try again.");
    } finally {
      setIsSaving(false);
    }
  };

  const rightComponent = () => {
    const shouldShow =
      shouldRemoveAvatar || selectedAsset || displayName !== user?.displayName;

    if (!shouldShow) return null;

    return (
      <Button.Wrapper onPress={handleSave} disabled={isSaving}>
        <Text>{isSaving ? "Saving..." : "Save"}</Text>
      </Button.Wrapper>
    );
  };

  return (
    <ScreenLayout paddings={{ paddingHorizontal: 16 }}>
      {isSaving && <Loading text="Saving..." />}
      <Block align="center">
        <GoBackHeader
          margins={{ marginBottom: 40 }}
          title="Profile"
          rightComp={rightComponent()}
        />
        <Block margins={{ marginBottom: 8 }}>
          {isLoading ? (
            <Block width={120} height={120} align="center" justify="center">
              <ActivityIndicator />
            </Block>
          ) : selectedAsset?.uri ? (
            <Button.Wrapper
              onPress={() =>
                selectedAsset.uri &&
                setImageViewerPayload({ uri: selectedAsset.uri })
              }
            >
              <Block
                width={120}
                height={120}
                align="center"
                justify="center"
                border={{ borderRadius: 999 }}
                overflow="hidden"
              >
                <Image
                  source={{ uri: selectedAsset.uri }}
                  width={120}
                  height={120}
                />
              </Block>
            </Button.Wrapper>
          ) : (
            <UserImage
              avatarUrl={userImageUri}
              displayName={user?.displayName}
              width={120}
              height={120}
              borderRadius={999}
              onPress={(uri) => setImageViewerPayload({ uri })}
            />
          )}
        </Block>
        <Block
          flexDirection="row"
          align="center"
          gap={12}
          margins={{ marginBottom: 40 }}
        >
          <Button.Wrapper
            onPress={() => setIsListOpen(true)}
            disabled={isLoading || isSaving}
          >
            <Block
              flexDirection="row"
              align="center"
              gap={12}
              paddings={[16, 12]}
            >
              <Image
                source={require("assets/icons/upload-simple-large.png")}
                width={16}
                height={16}
                tintColor={Colors.primary}
                style={styles.icon}
              />
              <Text size={TextSize.small} color={Colors.primary}>
                Upload
              </Text>
            </Block>
          </Button.Wrapper>
          <Button.Wrapper onPress={handleRemove} disabled={isSaving}>
            <Block
              flexDirection="row"
              align="center"
              gap={12}
              paddings={[16, 12]}
            >
              <Image
                source={require("assets/icons/trash.png")}
                width={16}
                height={16}
                style={styles.icon}
              />
              <Text size={TextSize.small}>Remove</Text>
            </Block>
          </Button.Wrapper>
        </Block>
      </Block>
      <Block>
        <Text margins={{ marginBottom: 20 }}>Contact info</Text>
        <Block gap={20}>
          <Block gap={8}>
            <Text
              size={TextSize.tiny}
              color={Colors.white50}
              paddings={[0, 16]}
            >
              Display name
            </Text>
            <Input
              placeholder="Display name"
              value={displayName}
              background={Colors.white5}
              onChangeText={(value) => setDisplayName(value)}
            />
            <Text
              size={TextSize.small}
              color={Colors.white50}
              paddings={[0, 16]}
            >
              This is what others will see whenever you’re signed in.
            </Text>
          </Block>
          <Block gap={8}>
            <Text
              size={TextSize.tiny}
              color={Colors.white50}
              paddings={[0, 16]}
            >
              Username
            </Text>
            <Block
              border={{
                borderRadius: 40,
              }}
              paddings={[10, 16]}
              background={Colors.white5}
            >
              <Text
                font="InstrumentSans-Regular"
                size={TextSize.small}
                color={Colors.white50}
              >
                {user?.userId}
              </Text>
            </Block>
          </Block>
        </Block>
      </Block>
      <Modal
        visible={isListOpen}
        transparent={true}
        presentationStyle="overFullScreen"
        animationType="fade"
      >
        <Block
          width="100%"
          height="100%"
          justify="flex-end"
          align="center"
          background={Colors.black70}
          paddings={[40, 20]}
        >
          {isLoading && <Loading />}
          <Block maxWidth={600} width="100%" gap={8}>
            <Block
              width="100%"
              background={Colors.blackMinus3}
              border={{ borderRadius: 14 }}
            >
              <SingleSendItem
                title="Chose photo"
                showSeparator
                onPress={handleChoosePhoto}
              />
              <SingleSendItem
                title="Take a photo"
                showSeparator
                onPress={handleTakePhoto}
              />
            </Block>
            <Block
              width="100%"
              background={Colors.blackMinus3}
              border={{ borderRadius: 14 }}
            >
              <SingleSendItem
                title="Cancel"
                onPress={() => setIsListOpen(false)}
              />
            </Block>
          </Block>
        </Block>
      </Modal>
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  icon: {
    width: 16,
    height: 16,
  },
  delete: {
    width: "100%",
    marginTop: 40,
  },
});

