                        style={styles.checkIcon}
                        tintColor={Colors.success}
                      />
                    )}
                  </Block>
                </Block>
              </Button.Wrapper>
            </Block>
          </Block>
        </Block>
      </Block>
    </ScreenLayout>
  );
