import { Block, type BlockProps } from "@prototyp/skeletor";
import type { FC, PropsWithChildren } from "react";
import { isIpad } from "shared/utils";

export const IpadScreenWrapper: FC<PropsWithChildren<BlockProps>> = ({
  children,
  ...props
}) => {
  const hasExtraProps = Object.keys(props).length > 0;

  if (!isIpad() && !hasExtraProps) return children;

  if (!isIpad() && hasExtraProps) {
    return <Block {...props}>{children}</Block>;
  }

  return (
    <Block
      flex={1}
      width="100%"
      maxWidth={680}
      margins={{ marginHorizontal: "auto" }}
      {...props}
    >
      {children}
    </Block>
  );
};

import { Block, Text } from "@prototyp/skeletor";
import { useIsFocused } from "@react-navigation/native";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import {
  MembershipState_Tags,
  StateEventType,
} from "@unomed/react-native-matrix-sdk";
import { useAtomValue, useSetAtom } from "jotai";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { NetworkAtoms } from "modules/network/jotai";
import { useRoomInfo, useRoomMembers } from "modules/room/hooks";
import { RoomAtoms } from "modules/room/jotai";
import { RoomService } from "modules/room/service/RoomService";
import { TimelineAtoms } from "modules/timeline/jotai";
import { useCallback, useEffect, useMemo, useState } from "react";
import { Image, StyleSheet, Switch } from "react-native";
import { SettingsListItem } from "screens/settings/fragments";
import {
  Button,
  GoBackHeader,
  IpadScreenWrapper,
  Loading,
  RoomImage,
  ScreenLayout,
} from "shared/components";
import { useLeaveRoom } from "shared/hooks";
import { Colors, TextSize } from "shared/styles";
import { offlineToastHelper } from "shared/utils";
import { ActionButtons, EncryptionStatus, Topic } from "./fragments";
import { LeaveRoom } from "./leave-room/LeaveRoom";

export const RoomDetails: React.FC<
  NativeStackScreenProps<Routes, "roomDetails">
> = ({ navigation, route }) => {
  const { room } = route.params;
  const roomInfo = useRoomInfo(room);
  const isFocused = useIsFocused();
  const isOffline = useAtomValue(NetworkAtoms.isOffline);
  const isDirect = roomInfo?.isDirect;
  const hasPowerLevelToCall =
    roomInfo?.powerLevels?.canOwnUserSendState(StateEventType.CallMember) ??
    false;
  const { members, fetchMembers } = useRoomMembers(room);
  const { isLeavingRoom, leaveRoom } = useLeaveRoom(room, members, {
    onSuccess: () => {
      navigation.reset({
        index: 0,
        routes: [{ name: "home" }],
      });
    },
  });
  const [isFavorite, setIsFavorite] = useState(false);
  const [isFavoriteLoading, setIsFavoriteLoading] = useState(false);
  const [userPowerLevel, setUserPowerLevel] = useState<number | null>(null);
  const [nameLevel, setNameLevel] = useState(50);
  const [avatarLevel, setAvatarLevel] = useState(50);
  const [topicLevel, setTopicLevel] = useState(50);
  const [inviteLevel, setInviteLevel] = useState<number>(50);
  const setRoomNotificationMode = useSetAtom(RoomAtoms.roomNotificationMode);
  const setImageViewerPayload = useSetAtom(TimelineAtoms.imageViewerPayload);

  const canSeeRoles = useMemo(
    () => !!userPowerLevel && userPowerLevel >= 50,
    [userPowerLevel],
  );
  const canEditName = useMemo(
    () => (userPowerLevel ?? 0) >= nameLevel,
    [userPowerLevel, nameLevel],
  );
  const canEditAvatar = useMemo(
    () => (userPowerLevel ?? 0) >= avatarLevel,
    [userPowerLevel, avatarLevel],
  );
  const canEditTopic = useMemo(
    () => (userPowerLevel ?? 0) >= topicLevel,
    [userPowerLevel, topicLevel],
  );
  const canEditRoom = useMemo(
    () => !isDirect && (canEditName || canEditAvatar || canEditTopic),
    [isDirect, canEditName, canEditAvatar, canEditTopic],
  );
  const canInvite = useMemo(
    () => !isDirect && userPowerLevel !== null && userPowerLevel >= inviteLevel,
    [userPowerLevel, inviteLevel],
  );
  const pinnedEventIds = useAtomValue(TimelineAtoms.pinnedEventIds);
  const otherDirectMember = useMemo(() => {
    return members.filter(
      (member) => member.userId !== MatrixCore.instance?.userId(),
    )[0];
  }, [members]);
  const otherDirectMembersId = otherDirectMember?.userId;

  // Sync isFavourite from live roomInfo
  useEffect(() => {
    if (!roomInfo) return;
    setIsFavorite(roomInfo.isFavourite ?? false);
  }, [roomInfo?.isFavourite]);

  useEffect(() => {
    if (!isFocused) return;

    RoomService.getUserPowerLevel(room.id())
      .then(setUserPowerLevel)
      .catch(console.error);

    RoomService.getRoomPowerLevels(room.id())
      .then((pl) => {
        if (!pl) return;
        const vals = pl.values();
        setNameLevel(Number(vals.roomName));
        setAvatarLevel(Number(vals.roomAvatar));
        setTopicLevel(Number(vals.roomTopic));
        setInviteLevel(Number(vals.invite));
      })
      .catch(console.error);

    MatrixCore.getClient()
      .getNotificationSettings()
      .then((ns) => ns.getUserDefinedRoomNotificationMode(room.id()))
      .then((mode) => setRoomNotificationMode(mode ?? null))
      .catch(console.error);
  }, [isFocused]);

  useEffect(() => {
    if (!isFocused) return;
    fetchMembers();
  }, [isFocused, fetchMembers]);

  const handleToggleFavourite = useCallback(async () => {
    if (isOffline) {
      offlineToastHelper("No internet connection");
      return;
    }

    if (isFavoriteLoading) return;
    setIsFavoriteLoading(true);
    setIsFavorite(!isFavorite);
    try {
      await room.setIsFavourite(!isFavorite, undefined);
    } catch (error) {
      setIsFavorite(isFavorite);
      console.error(error);
      offlineToastHelper(
        isFavorite
          ? "Failed to remove from favorites"
          : "Failed to add to favorites",
      );
    } finally {
      setIsFavoriteLoading(false);
    }
  }, [isFavorite, isOffline, isFavoriteLoading, room]);

  if (!roomInfo) return <Loading />;

  return (
    <ScreenLayout>
      {isLeavingRoom && <Loading text="Leaving room..." />}
      <GoBackHeader
        margins={{ marginBottom: 40 }}
        rightComp={
          canEditRoom && (
            <Button.Wrapper
              onPress={() =>
                navigation.navigate("editRoom", {
                  room,
                })
              }
            >
              <Text>Edit</Text>
            </Button.Wrapper>
          )
        }
      />
      <IpadScreenWrapper width="100%" scrollable>
        <Block align="center" gap={12}>
          <RoomImage
            onPress={(uri) => setImageViewerPayload({ uri })}
            room={room}
            width={80}
            height={80}
          />
          <Text size={TextSize.medium} font="InstrumentSans-Bold">
            {room.displayName()}
          </Text>
          {isDirect && roomInfo?.heroes[0]?.userId && (
            <Text color={Colors.white50}>{roomInfo?.heroes[0]?.userId}</Text>
          )}
          <EncryptionStatus roomInfo={roomInfo} />
        </Block>
        <ActionButtons
          room={room}
          members={members}
          hasPowerLevelToCall={hasPowerLevelToCall}
          canInvite={canInvite}
        />
        <Topic room={room} topic={roomInfo?.topic} canEdit={canEditTopic} />
        <Block
          border={{ borderRadius: 16 }}
          width="100%"
          background={Colors.white5}
          margins={{ marginBottom: 20 }}
        >
          <SettingsListItem
            title="Notifications"
            icon={require("assets/icons/bell.png")}
            showSeparator
            onPress={() =>
              navigation.navigate("roomNotifications", { roomId: room.id() })
            }
          />
          <SettingsListItem
            title="Favorite"
            icon={require("assets/icons/star.png")}
            showSeparator
            onPress={handleToggleFavourite}
            rightComp={
              <Block paddings={{ paddingRight: 12 }}>
                <Switch
                  value={isFavorite}
                  disabled={isFavoriteLoading}
                  trackColor={{ true: Colors.primary, false: Colors.white20 }}
                  onValueChange={handleToggleFavourite}
                />
              </Block>
            }
          />
          {isDirect ? (
            <Button.Wrapper
              onPress={() =>
                navigation.navigate("profile", {
                  userId: otherDirectMembersId,
                  initialProfile: otherDirectMember
                    ? {
                        userId: otherDirectMember.userId,
                        displayName: otherDirectMember.displayName,
                        avatarUrl: otherDirectMember.avatarUrl,
                      }
                    : undefined,
                })
              }
            >
              <Block paddings={[0, 12]}>
                <Block
                  flexDirection="row"
                  align="center"
                  gap={12}
                  paddings={[20, 0]}
                  border={{ borderBottomWidth: 1, borderColor: Colors.white5 }}
                >
                  <Image
                    source={require("assets/icons/user.png")}
                    tintColor={Colors.white50}
                    width={24}
                    height={24}
                  />
                  <Text>View profile</Text>
                  <Block
                    margins={{ marginLeft: "auto" }}
                    flexDirection="row"
                    align="center"
                    gap={8}
                  >
                    <Image
                      source={require("assets/icons/caret-left.png")}
                      style={styles.caret}
                      tintColor={Colors.white50}
                    />
                  </Block>
                </Block>
              </Block>
            </Button.Wrapper>
          ) : (
            <Button.Wrapper
              onPress={() =>
                navigation.navigate("roomMembers", {
                  roomId: room.id(),
                })
              }
            >
              <Block paddings={[0, 12]}>
                <Block
                  flexDirection="row"
                  align="center"
                  gap={12}
                  paddings={[20, 0]}
                  border={{ borderBottomWidth: 1, borderColor: Colors.white5 }}
                >
                  <Image
                    source={require("assets/icons/users.png")}
                    tintColor={Colors.white50}
                    width={24}
                    height={24}
                  />
                  <Text>Members</Text>
                  <Block
                    margins={{ marginLeft: "auto" }}
                    flexDirection="row"
                    align="center"
                    gap={8}
                  >
                    <Text color={Colors.white50}>
                      (
                      {
                        members.filter(
                          (m) =>
                            m.membership?.tag === MembershipState_Tags.Join,
                        ).length
                      }
                      )
                    </Text>
                    <Image
                      source={require("assets/icons/caret-left.png")}
                      style={styles.caret}
                      tintColor={Colors.white50}
                    />
                  </Block>
                </Block>
              </Block>
            </Button.Wrapper>
          )}
          {!isDirect && canSeeRoles && (
            <SettingsListItem
              title="Security & Privacy"
              icon={require("assets/icons/shield.png")}
              showSeparator
              onPress={() => navigation.navigate("roomSecurity", { room })}
            />
          )}
          {!isDirect && canSeeRoles && (
            <SettingsListItem
              title="Roles & Permissions"
              icon={require("assets/icons/user.png")}
              showSeparator
              onPress={() =>
                navigation.navigate("roomRoles", {
                  room,
                  userPowerLevel: userPowerLevel ?? 0,
                })
              }
            />
          )}
          <SettingsListItem
            title="Media and Files"
            icon={require("assets/icons/image.png")}
            onPress={() => navigation.navigate("roomMedia", { room })}
            showSeparator={!!pinnedEventIds.length}
          />
          {!!pinnedEventIds.length && (
            <SettingsListItem
              title="Pinned events"
              icon={require("assets/icons/pin.png")}
              onPress={() => navigation.navigate("pinnedEvents", { room })}
            />
          )}
        </Block>
        <LeaveRoom onPress={leaveRoom} />
      </IpadScreenWrapper>
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  caret: {
    transform: [{ rotate: "180deg" }],
    width: 24,
    height: 24,
    marginLeft: "auto",
  },
});

import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { useAtomValue, useSetAtom } from "jotai";
import { StorageAtoms } from "modules/storage/jotai/atoms";
import { TimelineAtoms } from "modules/timeline/jotai/atoms";
import { UserService } from "modules/user/service/UserService";
import { useState } from "react";
import { ActivityIndicator, Image, Modal, StyleSheet } from "react-native";
import type { Asset } from "react-native-image-picker";
import Toast from "react-native-toast-message";
import { SingleSendItem } from "screens/room/fragments/single-send-item";
import {
  Button,
  GoBackHeader,
  Input,
  Loading,
  ScreenLayout,
  UserImage,
} from "shared/components";
import { useUploadPhoto } from "shared/hooks";
import { Colors, TextSize } from "shared/styles";
import { offlineToastHelper } from "shared/utils";

export const UserProfile: React.FC<
  NativeStackScreenProps<Routes, "userProfile">
> = () => {
  const user = useAtomValue(StorageAtoms.cachedProfile);
  const [userImageUri, setUserImageUri] = useState<string | undefined>(
    user?.avatarUrl,
  );
  const {
    isLoading,
    selectedAsset,
    isListOpen,
    setSelectedAsset,
    setIsListOpen,
    handleChoosePhoto,
    handleTakePhoto,
  } = useUploadPhoto();
  const [displayName, setDisplayName] = useState<string | undefined>(
    user?.displayName,
  );
  const [isSaving, setIsSaving] = useState(false);
  const [shouldRemoveAvatar, setShouldRemoveAvatar] = useState(false);
  const setImageViewerPayload = useSetAtom(TimelineAtoms.imageViewerPayload);

  const handleRemove = () => {
    setUserImageUri(undefined);
    setSelectedAsset(null);
    setShouldRemoveAvatar(true);
  };

  const handleSave = async () => {
    try {
      setIsSaving(true);

      let avatarToUpload: Asset | null | undefined;

      if (shouldRemoveAvatar) {
        avatarToUpload = null; // User wants to remove avatar
      } else if (selectedAsset) avatarToUpload = selectedAsset;

      const updated = await UserService.updateProfile(
        displayName,
        avatarToUpload,
      );

      setShouldRemoveAvatar(false);
      setSelectedAsset(null);

      // The user state will be automatically updated via the atom
      setUserImageUri(updated?.avatarUrl);
      setDisplayName(updated?.displayName);

      Toast.show({
        type: "success",
        text1: "Profile updated successfully",
      });
    } catch (error) {
      console.error("Failed to update profile:", error);
      offlineToastHelper("Failed to update profile. Please try again.");
    } finally {
      setIsSaving(false);
    }
  };

  const rightComponent = () => {
    const shouldShow =
      shouldRemoveAvatar || selectedAsset || displayName !== user?.displayName;

    if (!shouldShow) return null;

    return (
      <Button.Wrapper onPress={handleSave} disabled={isSaving}>
        <Text>{isSaving ? "Saving..." : "Save"}</Text>
      </Button.Wrapper>
    );
  };

  return (
    <ScreenLayout paddings={{ paddingHorizontal: 16 }}>
      {isSaving && <Loading text="Saving..." />}
      <Block align="center">
        <GoBackHeader
          margins={{ marginBottom: 40 }}
          title="Profile"
          rightComp={rightComponent()}
        />
        <Block margins={{ marginBottom: 8 }}>
          {isLoading ? (
            <Block width={120} height={120} align="center" justify="center">
              <ActivityIndicator />
            </Block>
          ) : selectedAsset?.uri ? (
            <Button.Wrapper
              onPress={() =>
                selectedAsset.uri &&
                setImageViewerPayload({ uri: selectedAsset.uri })
              }
            >
              <Block
                width={120}
                height={120}
                align="center"
                justify="center"
                border={{ borderRadius: 999 }}
                overflow="hidden"
              >
                <Image
                  source={{ uri: selectedAsset.uri }}
                  width={120}
                  height={120}
                />
              </Block>
            </Button.Wrapper>
          ) : (
            <UserImage
              avatarUrl={userImageUri}
              displayName={user?.displayName}
              width={120}
              height={120}
              borderRadius={999}
              onPress={(uri) => setImageViewerPayload({ uri })}
            />
          )}
        </Block>
        <Block
          flexDirection="row"
          align="center"
          gap={12}
          margins={{ marginBottom: 40 }}
        >
          <Button.Wrapper
            onPress={() => setIsListOpen(true)}
            disabled={isLoading || isSaving}
          >
            <Block
              flexDirection="row"
              align="center"
              gap={12}
              paddings={[16, 12]}
            >
              <Image
                source={require("assets/icons/upload-simple-large.png")}
                width={16}
                height={16}
                tintColor={Colors.primary}
                style={styles.icon}
              />
              <Text size={TextSize.small} color={Colors.primary}>
                Upload
              </Text>
            </Block>
          </Button.Wrapper>
          <Button.Wrapper onPress={handleRemove} disabled={isSaving}>
            <Block
              flexDirection="row"
              align="center"
              gap={12}
              paddings={[16, 12]}
            >
              <Image
                source={require("assets/icons/trash.png")}
                width={16}
                height={16}
                style={styles.icon}
              />
              <Text size={TextSize.small}>Remove</Text>
            </Block>
          </Button.Wrapper>
        </Block>
      </Block>
      <Block>
        <Text margins={{ marginBottom: 20 }}>Contact info</Text>
        <Block gap={20}>
          <Block gap={8}>
            <Text
              size={TextSize.tiny}
              color={Colors.white50}
              paddings={[0, 16]}
            >
              Display name
            </Text>
            <Input
              placeholder="Display name"
              value={displayName}
              background={Colors.white5}
              onChangeText={(value) => setDisplayName(value)}
            />
            <Text
              size={TextSize.small}
              color={Colors.white50}
              paddings={[0, 16]}
            >
              This is what others will see whenever you’re signed in.
            </Text>
          </Block>
          <Block gap={8}>
            <Text
              size={TextSize.tiny}
              color={Colors.white50}
              paddings={[0, 16]}
            >
              Username
            </Text>
            <Block
              border={{
                borderRadius: 40,
              }}
              paddings={[10, 16]}
              background={Colors.white5}
            >
              <Text
                font="InstrumentSans-Regular"
                size={TextSize.small}
                color={Colors.white50}
              >
                {user?.userId}
              </Text>
            </Block>
          </Block>
        </Block>
      </Block>
      <Modal
        visible={isListOpen}
        transparent={true}
        presentationStyle="overFullScreen"
        animationType="fade"
      >
        <Block
          width="100%"
          height="100%"
          justify="flex-end"
          align="center"
          background={Colors.black70}
          paddings={[40, 20]}
        >
          {isLoading && <Loading />}
          <Block maxWidth={600} width="100%" gap={8}>
            <Block
              width="100%"
              background={Colors.blackMinus3}
              border={{ borderRadius: 14 }}
            >
              <SingleSendItem
                title="Chose photo"
                showSeparator
                onPress={handleChoosePhoto}
              />
              <SingleSendItem
                title="Take a photo"
                showSeparator
                onPress={handleTakePhoto}
              />
            </Block>
            <Block
              width="100%"
              background={Colors.blackMinus3}
              border={{ borderRadius: 14 }}
            >
              <SingleSendItem
                title="Cancel"
                onPress={() => setIsListOpen(false)}
              />
            </Block>
          </Block>
        </Block>
      </Modal>
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  icon: {
    width: 16,
    height: 16,
  },
  delete: {
    width: "100%",
    marginTop: 40,
  },
});

import { BottomSheetView } from "@gorhom/bottom-sheet";
import { Block, Text } from "@prototyp/skeletor";
import { RecoveryState } from "@unomed/react-native-matrix-sdk";
import { AuthService } from "modules/auth/service/AuthService";
import { EncryptionService } from "modules/encryption/service/EncryptionService";
import { NavigationContainerRef } from "modules/navigation/const";
import { useCallback, useEffect, useRef, useState } from "react";
import { Image } from "react-native";
import Toast from "react-native-toast-message";
import { Button, Loading } from "shared/components";
import {
  AppBottomSheet,
  type AppBottomSheetRef,
} from "shared/components/bottom-sheet";
import { usePreventSwipeBack } from "shared/hooks";
import { Colors, TextSize } from "shared/styles";
import { offlineToastHelper } from "shared/utils";

interface Props {
  isBottomSheetOpen: boolean;
  setIsBottomSheetOpen: () => void;
}

export const SignOutBottomSheet: React.FC<Props> = ({
  isBottomSheetOpen,
  setIsBottomSheetOpen,
}) => {
  const sheetRef = useRef<AppBottomSheetRef>(null);
  const [backupState, setBackupState] = useState<MappedBackupState>("unknown");
  const [recoveryState, setRecoveryState] = useState<RecoveryState>(
    RecoveryState.Unknown,
  );
  const isBackupEnabled =
    backupState === "enabled" ||
    (backupState === "unknown" &&
      (recoveryState === RecoveryState.Enabled ||
        recoveryState === RecoveryState.Incomplete));
  const [showBackupSetUpWarning, setShowBackupSetUpWarning] = useState(false);
  const [isSigningOut, setIsSigningOut] = useState(false);

  const signOut = async () => {
    try {
      setIsSigningOut(true);
      await AuthService.logout();
      handleCancel();
      NavigationContainerRef.reset({
        index: 0,
        routes: [{ name: "splash" }],
      });
      Toast.show({
        type: "success",
        text1: "Successfully signed out",
      });
    } catch (error) {
      console.error("Failed to logout: ", error);
      offlineToastHelper("Failed to sign out");
    } finally {
      setIsSigningOut(false);
    }
  };

  const handleClose = useCallback(() => {
    setIsBottomSheetOpen();
    setShowBackupSetUpWarning(false);
  }, [setIsBottomSheetOpen]);

  const handleCancel = useCallback(() => {
    sheetRef.current?.close();
  }, []);

  const handleSettings = useCallback(() => {
    handleCancel();
    NavigationContainerRef.navigate("encryption");
  }, [handleCancel]);

  const handleSignOut = useCallback(() => {
    if (!isBackupEnabled) {
      setShowBackupSetUpWarning(true);
      return;
    }

    signOut();
  }, [signOut]);

  usePreventSwipeBack(isBottomSheetOpen);

  useEffect(() => {
    const listener = EncryptionService.subscribeToBackupState((state) => {
      setBackupState(state);
    });

    return () => {
      listener.cancel();
    };
  }, []);

  useEffect(() => {
    const listener = EncryptionService.subscribeToRecoveryState((state) => {
      setRecoveryState(state);
    });

    return () => {
      listener.cancel();
    };
  }, []);

  return (
    <>
      {isSigningOut ? <Loading text="Signing out..." /> : null}
      <AppBottomSheet
        ref={sheetRef}
        isOpen={isBottomSheetOpen}
        onClose={handleClose}
      >
        <BottomSheetView>
          {showBackupSetUpWarning ? (
            <Block
              paddings={{
                paddingHorizontal: 20,
                paddingBottom: 20,
              }}
              gap={40}
              align="center"
            >
              <Image source={require("assets/images/key.png")} />
              <Block gap={8} align="center">
                <Text size={TextSize.large} color={Colors.white}>
                  Recovery not set up
                </Text>
                <Text font="InstrumentSans-Regular" textAlign="center">
                  You are about to sign out of your last session. If you sign
                  out now, you will lose access to your encrypted messages.
                </Text>
              </Block>
              <Block gap={12} width="100%" paddings={[0, 52]}>
                <Button.Outline onPress={handleSettings}>
                  Settings
                </Button.Outline>
                <Button.Warning onPress={signOut}>
                  Sign out anyway
                </Button.Warning>
              </Block>
            </Block>
          ) : (
            <Block
              paddings={{
                paddingHorizontal: 20,
                paddingBottom: 20,
              }}
              gap={40}
            >
              <Block gap={8} align="center">
                <Text size={TextSize.large} color={Colors.white}>
                  Sign Out
                </Text>
                <Text font="InstrumentSans-Regular">
                  Are you sure you want to sign out?
                </Text>
              </Block>
              <Block gap={12} width="100%" paddings={[0, 52]}>
                <Button.Warning onPress={handleSignOut}>
                  Sign Out
                </Button.Warning>
                <Button.Ghost onPress={handleCancel}>Cancel</Button.Ghost>
              </Block>
            </Block>
          )}
        </BottomSheetView>
      </AppBottomSheet>
    </>
  );
};

import { useAtomValue } from "jotai";
import { NavigationContainerRef } from "modules/navigation/const";
import { PushNotificationsAtoms } from "modules/push-notifications/jotai";
import { StorageAtoms } from "modules/storage/jotai/atoms";

export const useNavigateToCorrectScreenHelper = () => {
  const hasSeenNotificationsIntro = useAtomValue(
    PushNotificationsAtoms.hasSeenNotificationsIntro,
  );
  const hasSeenOnboarding = useAtomValue(StorageAtoms.hasSeenOnboarding);

  return () => {
    if (!hasSeenOnboarding) {
      NavigationContainerRef.reset({
        index: 0,
        routes: [{ name: "onboarding" }],
      });
      return;
    }

    if (!hasSeenNotificationsIntro) {
      NavigationContainerRef.reset({
        index: 0,
        routes: [{ name: "notificationsIntro" }],
      });
      return;
    }

    NavigationContainerRef.reset({
      index: 0,
      routes: [{ name: "home" }],
    });
  };
};

