1	import { Block, Text } from "@prototyp/skeletor";
2	import { useIsFocused } from "@react-navigation/native";
3	import type { NativeStackScreenProps } from "@react-navigation/native-stack";
4	import { FlashList } from "@shopify/flash-list";
5	import {
6	  MembershipState_Tags,
7	  PowerLevel_Tags,
8	  type RoomMember,
9	} from "@unomed/react-native-matrix-sdk";
10	import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
11	import { NavigationContainerRef } from "modules/navigation/const";
12	import { useRoomMembers } from "modules/room/hooks";
13	import { RoomService } from "modules/room/service/RoomService";
14	import { useCallback, useEffect, useMemo, useState } from "react";
15	import { Image, StyleSheet } from "react-native";
16	import { Button, Loading, MemberDetailsBottomSheet } from "shared/components";
17	import { GoBackHeader } from "shared/components/go-back-header/GoBackHeader";
18	import { ScreenLayout } from "shared/components/screen-layout/ScreenLayout";
19	import { UserImage } from "shared/components/user-image/UserImage";
20	import { useMemberDetails } from "shared/hooks";
21	import { Colors, TextSize } from "shared/styles";
22	import { getLevelLabel } from "shared/utils";
23	
24	type SectionHeader = { type: "header"; title: string };
25	type SectionItem = { type: "member"; member: RoomMember };
26	type ListItem = SectionHeader | SectionItem;
27	
28	const getRolePriority = (member: RoomMember) => {
29	  if (member.powerLevel.tag !== PowerLevel_Tags.Value) return 2;
30	
31	  const levelLabel = getLevelLabel(Number(member.powerLevel.inner.value));
32	  if (levelLabel === "Admin") return 0;
33	  if (levelLabel === "Moderator") return 1;
34	  return 2;
35	};
36	
37	const sortMembers = (a: RoomMember, b: RoomMember) => {
38	  const priorityDiff = getRolePriority(a) - getRolePriority(b);
39	  if (priorityDiff !== 0) return priorityDiff;
40	
41	  const aName = (a.displayName ?? a.userId).trim();
42	  const bName = (b.displayName ?? b.userId).trim();
43	  return aName.localeCompare(bName, undefined, { sensitivity: "base" });
44	};
45	
46	export const RoomMembers: React.FC<
47	  NativeStackScreenProps<Routes, "roomMembers">
48	> = ({ route }) => {
49	  const { roomId } = route.params;
50	  const room = useMemo(() => RoomService.getRoomInfo(roomId), [roomId]);
51	  const { members, isLoading, fetchMembers } = useRoomMembers(
52	    room ?? undefined,
53	  );
54	  const [canInvite, setCanInvite] = useState(false);
55	  const isFocused = useIsFocused();
56	  const {
57	    selectedMember,
58	    isBottomSheetOpen,
59	    openMemberDetails,
60	    closeMemberDetails,
61	  } = useMemberDetails();
62	
63	  const pendingMembers = useMemo(
64	    () =>
65	      members.filter(
66	        (member) => member.membership?.tag === MembershipState_Tags.Invite,
67	      ),
68	    [members],
69	  );
70	  const acceptedMembers = useMemo(
71	    () =>
72	      members
73	        .filter(
74	          (member) => member.membership?.tag === MembershipState_Tags.Join,
75	        )
76	        .sort(sortMembers),
77	    [members],
78	  );
79	  const bannedMembers = useMemo(
80	    () =>
81	      members.filter(
82	        (member) => member.membership?.tag === MembershipState_Tags.Ban,
83	      ),
84	    [members],
85	  );
86	
87	  const listData = useMemo<ListItem[]>(() => {
88	    const items: ListItem[] = [];
89	
90	    if (pendingMembers.length) {
91	      items.push({ type: "header", title: "Pending" });
92	      pendingMembers.forEach((member) =>
93	        items.push({ type: "member", member }),
94	      );
95	    }
96	
97	    if (acceptedMembers.length) {
98	      items.push({
99	        type: "header",
100	        title: `${acceptedMembers.length} ${acceptedMembers.length === 1 ? "member" : "members"}`,
101	      });
102	      acceptedMembers.forEach((member) =>
103	        items.push({ type: "member", member }),
104	      );
105	    }
106	
107	    if (bannedMembers.length) {
108	      items.push({ type: "header", title: "Banned" });
109	      bannedMembers.forEach((member) => items.push({ type: "member", member }));
110	    }
111	
112	    return items;
113	  }, [pendingMembers, acceptedMembers, bannedMembers]);
114	
115	  const handleMemberAction = useCallback(
116	    (_userId: string, _action: "remove" | "ban" | "unban") => {
117	      setTimeout(fetchMembers, 2000);
118	    },
119	    [fetchMembers],
120	  );
121	
122	  const handleMemberPress = useCallback(
123	    (member: RoomMember) => {
124	      openMemberDetails({
125	        userId: member.userId,
126	        displayName: member.displayName ?? "Unknown",
127	        avatarUrl: member.avatarUrl ?? null,
128	        membershipTag: member.membership?.tag,
129	      });
130	    },
131	    [openMemberDetails],
132	  );
133	
134	  useEffect(() => {
135	    if (!isFocused) return;
136	    fetchMembers();
137	  }, [isFocused, fetchMembers]);
138	
139	  useEffect(() => {
140	    const checkInvitePermission = async () => {
141	      const myUserId = MatrixCore.instance?.userId();
142	      if (!myUserId) return;
143	
144	      const powerLevels = await RoomService.getRoomPowerLevels(roomId);
145	      if (!powerLevels) return;
146	
147	      const inviteLevel = Number(powerLevels.values().invite);
148	      const myLevel = Number(powerLevels.userPowerLevels().get(myUserId) ?? 0);
149	      setCanInvite(myLevel >= inviteLevel);
150	    };
151	
152	    checkInvitePermission().catch(console.error);
153	  }, [roomId]);
154	
155	  return (
156	    <ScreenLayout>
157	      {isLoading && <Loading text="Loading members..." />}
158	      <Block align="center" width="100%" flex={1}>
159	        <GoBackHeader
160	          title="Members"
161	          margins={0}
162	          rightComp={
163	            canInvite && (
164	              <Button.Wrapper
165	                onPress={() =>
166	                  NavigationContainerRef.navigate("invitePeople", {
167	                    roomId,
168	                    members,
169	                  })
170	                }
171	              >
172	                <Image
173	                  source={require("assets/icons/plus.png")}
174	                  tintColor={Colors.white}
175	                  width={24}
176	                  height={24}
177	                />
178	              </Button.Wrapper>
179	            )
180	          }
181	        />
182	        <FlashList
183	          data={listData}
184	          style={styles.container}
185	          contentContainerStyle={styles.contentContainer}
186	          getItemType={(item) => item.type}
187	          keyExtractor={(item) =>
188	            item.type === "header" ? `header-${item.title}` : item.member.userId
189	          }
190	          renderItem={({ item }) => {
191	            if (item.type === "header") {
192	              return (
193	                <Block margins={{ marginBottom: 8 }}>
194	                  <Text size={TextSize.tiny} color={Colors.white80}>
195	                    {item.title}
196	                  </Text>
197	                </Block>
198	              );
199	            }
200	
201	            const { member } = item;
202	            return (
203	              <Button.Wrapper onPress={() => handleMemberPress(member)}>
204	                <Block
205	                  width="100%"
206	                  flexDirection="row"
207	                  align="center"
208	                  justify="space-between"
209	                  gap={12}
210	                  margins={{ marginBottom: 12 }}
211	                >
212	                  <Block flexDirection="row" align="center" gap={12} flex={1}>
213	                    <UserImage
214	                      avatarUrl={member.avatarUrl}
215	                      displayName={member.displayName}
216	                      width={40}
217	                      height={40}
218	                    />
219	                    <Block flex={1}>
220	                      <Text numberOfLines={1}>{member.displayName}</Text>
221	                      <Text
222	                        numberOfLines={1}
223	                        size={TextSize.tiny}
224	                        color={Colors.white50}
225	                      >
226	                        {member.userId}
227	                      </Text>
228	                    </Block>
229	                  </Block>
230	                  {member.powerLevel.tag === PowerLevel_Tags.Value &&
231	                    getLevelLabel(Number(member.powerLevel.inner.value)) !==
232	                      "Member" && (
233	                      <Block>
234	                        <Text color={Colors.white50}>
235	                          {getLevelLabel(Number(member.powerLevel.inner.value))}
236	                        </Text>
237	                      </Block>
238	                    )}
239	                </Block>
240	              </Button.Wrapper>
241	            );
242	          }}
243	        />
244	      </Block>
245	      <MemberDetailsBottomSheet
246	        isBottomSheetOpen={isBottomSheetOpen}
247	        selectedMember={selectedMember}
248	        roomId={roomId}
249	        onClose={closeMemberDetails}
250	        onMemberAction={handleMemberAction}
251	      />
252	    </ScreenLayout>
253	  );
254	};
255	
256	const styles = StyleSheet.create({
257	  container: {
258	    width: "100%",
259	    gap: 12,
260	    marginTop: 36,
261	    padding: 0,
262	  },
263	  contentContainer: {
264	    width: "100%",
265	    gap: 12,
266	  },
267	});
