1	import { Block, Text } from "@prototyp/skeletor";
2	import type { NativeStackScreenProps } from "@react-navigation/native-stack";
3	import { RoomService } from "modules/room/service/RoomService";
4	import { useEffect, useState } from "react";
5	import { ActivityIndicator, Image, Modal, StyleSheet } from "react-native";
6	import type { Asset } from "react-native-image-picker";
7	import Toast from "react-native-toast-message";
8	import { SingleSendItem } from "screens/room/fragments/single-send-item";
9	import {
10	  Button,
11	  GoBackHeader,
12	  Input,
13	  Loading,
14	  RoomImage,
15	  ScreenLayout,
16	} from "shared/components";
17	import { useUploadPhoto } from "shared/hooks";
18	import { Colors, TextSize } from "shared/styles";
19	import { offlineToastHelper } from "shared/utils";
20	
21	export const EditRoom: React.FC<NativeStackScreenProps<Routes, "editRoom">> = ({
22	  route,
23	}) => {
24	  const { room } = route.params;
25	  const {
26	    isLoading,
27	    selectedAsset,
28	    isListOpen,
29	    handleChoosePhoto,
30	    handleTakePhoto,
31	    setIsListOpen,
32	    setSelectedAsset,
33	  } = useUploadPhoto();
34	  const [displayName, setDisplayName] = useState<string | undefined>(
35	    room?.displayName(),
36	  );
37	  const [topic, setTopic] = useState<string | undefined>(room?.topic());
38	  const [isSaving, setIsSaving] = useState(false);
39	  const [shouldRemoveAvatar, setShouldRemoveAvatar] = useState(false);
40	  const [isDirect, setIsDirect] = useState(false);
41	  const [userPowerLevel, setUserPowerLevel] = useState(0);
42	  const [nameLevel, setNameLevel] = useState(50);
43	  const [avatarLevel, setAvatarLevel] = useState(50);
44	  const [topicLevel, setTopicLevel] = useState(50);
45	  const canEditName = userPowerLevel >= nameLevel;
46	  const canEditAvatar = userPowerLevel >= avatarLevel;
47	  const canEditTopic = userPowerLevel >= topicLevel;
48	
49	  const isRemoveDisabled = () => {
50	    if (isSaving || isDirect) return true;
51	
52	    if (selectedAsset) return false;
53	
54	    if (room.heroes()[0]?.avatarUrl || room.avatarUrl()) return false;
55	
56	    return true;
57	  };
58	
59	  useEffect(() => {
60	    room.isDirect().then(setIsDirect).catch(console.error);
61	    RoomService.getUserPowerLevel(room.id())
62	      .then((level) => setUserPowerLevel(level ?? 0))
63	      .catch(console.error);
64	    RoomService.getRoomPowerLevels(room.id())
65	      .then((pl) => {
66	        if (!pl) return;
67	        const vals = pl.values();
68	        setNameLevel(Number(vals.roomName));
69	        setAvatarLevel(Number(vals.roomAvatar));
70	        setTopicLevel(Number(vals.roomTopic));
71	      })
72	      .catch(console.error);
73	  }, [room]);
74	
75	  const handleRemove = () => {
76	    setSelectedAsset(null);
77	    setShouldRemoveAvatar(true);
78	  };
79	
80	  const handleSave = async () => {
81	    try {
82	      setIsSaving(true);
83	
84	      let avatarToUpload: Asset | null | undefined;
85	
86	      if (shouldRemoveAvatar) {
87	        avatarToUpload = null; // User wants to remove avatar
88	      } else if (selectedAsset) avatarToUpload = selectedAsset;
89	
90	      await RoomService.updateRoom(
91	        room.id(),
92	        displayName === room?.displayName() ? undefined : displayName, //if the displayName is the same as the room's displayName, don't update it
93	        topic === room?.topic() ? undefined : topic, //if the topic is the same as the room's topic, don't update it
94	        avatarToUpload,
95	      );
96	
97	      Toast.show({
98	        type: "success",
99	        text1: "Room updated successfully",
100	      });
101	    } catch (error) {
102	      console.error("Failed to update room:", error);
103	      offlineToastHelper("Failed to update room. Please try again.");
104	    } finally {
105	      setIsSaving(false);
106	    }
107	  };
108	
109	  const rightComponent = () => {
110	    const shouldShow =
111	      shouldRemoveAvatar ||
112	      selectedAsset ||
113	      displayName !== room?.displayName() ||
114	      topic !== room?.topic();
115	
116	    if (!shouldShow) return null;
117	
118	    return (
119	      <Button.Wrapper onPress={handleSave} disabled={isSaving}>
120	        <Text>{isSaving ? "Saving..." : "Save"}</Text>
121	      </Button.Wrapper>
122	    );
123	  };
124	
125	  if (!room) return null;
126	
127	  return (
128	    <ScreenLayout>
129	      {isSaving && <Loading text="Saving..." />}
130	      <Block align="center">
131	        <GoBackHeader
132	          title="Edit Room Deatils"
133	          rightComp={rightComponent()}
134	          margins={{ marginBottom: 40 }}
135	        />
136	        <Block margins={{ marginBottom: 8 }}>
137	          {isLoading ? (
138	            <Block width={120} height={120} align="center" justify="center">
139	              <ActivityIndicator />
140	            </Block>
141	          ) : selectedAsset?.uri ? (
142	            <Block
143	              width={120}
144	              height={120}
145	              align="center"
146	              justify="center"
147	              border={{ borderRadius: 999 }}
148	              overflow="hidden"
149	            >
150	              <Image
151	                source={{ uri: selectedAsset.uri }}
152	                width={120}
153	                height={120}
154	              />
155	            </Block>
156	          ) : shouldRemoveAvatar ? (
157	            <Block
158	              width={120}
159	              height={120}
160	              border={{
161	                borderRadius: 999,
162	                borderWidth: 2,
163	                borderColor: Colors.white20,
164	              }}
165	              background={Colors.white20}
166	              align="center"
167	              justify="center"
168	            >
169	              <Text
170	                size={TextSize.large}
171	                color="white"
172	                textTransform="uppercase"
173	              >
174	                {room.displayName()?.charAt(0)}
175	              </Text>
176	            </Block>
177	          ) : (
178	            <RoomImage
179	              borderRadius={999}
180	              room={room}
181	              width={120}
182	              height={120}
183	            />
184	          )}
185	        </Block>
186	        {!isDirect && canEditAvatar && (
187	          <Block
188	            flexDirection="row"
189	            align="center"
190	            gap={12}
191	            margins={{ marginBottom: 40 }}
192	          >
193	            <Button.Wrapper
194	              onPress={() => setIsListOpen(true)}
195	              disabled={isLoading || isSaving}
196	            >
197	              <Block
198	                flexDirection="row"
199	                align="center"
200	                gap={12}
201	                paddings={[16, 12]}
202	              >
203	                <Image
204	                  source={require("assets/icons/upload-simple-large.png")}
205	                  width={16}
206	                  height={16}
207	                  style={styles.icon}
208	                  tintColor={Colors.primary}
209	                />
210	                <Text size={TextSize.small} color={Colors.primary}>
211	                  Upload
212	                </Text>
213	              </Block>
214	            </Button.Wrapper>
215	            <Button.Wrapper
216	              onPress={handleRemove}
217	              disabled={isRemoveDisabled()}
218	            >
219	              <Block
220	                flexDirection="row"
221	                align="center"
222	                gap={12}
223	                paddings={[16, 12]}
224	              >
225	                <Image
226	                  source={require("assets/icons/trash.png")}
227	                  width={16}
228	                  height={16}
229	                  style={styles.icon}
230	                />
231	                <Text size={TextSize.small}>Remove</Text>
232	              </Block>
233	            </Button.Wrapper>
234	          </Block>
235	        )}
236	      </Block>
237	      <Block gap={20}>
238	        <Block gap={8}>
239	          <Text size={TextSize.tiny} color={Colors.white50} paddings={[0, 16]}>
240	            Display name
241	          </Text>
242	          <Input
243	            placeholder="Display name"
244	            value={displayName}
245	            disabled={isDirect || !canEditName}
246	            onChangeText={(value) => setDisplayName(value)}
247	          />
248	        </Block>
249	        <Block gap={8}>
250	          <Text size={TextSize.tiny} color={Colors.white50} paddings={[0, 16]}>
251	            Topic
252	          </Text>
253	          <Input
254	            placeholder="Add a topic"
255	            value={topic}
256	            disabled={!canEditTopic}
257	            onChangeText={(value) => setTopic(value)}
258	          />
259	        </Block>
260	      </Block>
261	      <Modal
262	        visible={isListOpen}
263	        transparent={true}
264	        presentationStyle="overFullScreen"
265	        animationType="fade"
266	      >
267	        <Block
268	          width="100%"
269	          height="100%"
270	          justify="flex-end"
271	          align="center"
272	          background={Colors.black70}
273	          paddings={[40, 20]}
274	        >
275	          {isLoading && <Loading />}
276	          <Block maxWidth={600} width="100%" gap={8}>
277	            <Block
278	              width="100%"
279	              background={Colors.blackMinus3}
280	              border={{ borderRadius: 14 }}
281	            >
282	              <SingleSendItem
