              border={{ borderRadius: 999 }}
              overflow="hidden"
            >
              <Image
                source={{ uri: selectedAsset.uri }}
                width={120}
                height={120}
              />
            </Block>
          ) : shouldRemoveAvatar ? (
            <Block
              width={120}
              height={120}
              border={{
                borderRadius: 999,
                borderWidth: 2,
                borderColor: Colors.white20,
              }}
              background={Colors.white20}
              align="center"
              justify="center"
            >
              <Text
                size={TextSize.large}
                color="white"
                textTransform="uppercase"
              >
                {room.displayName()?.charAt(0)}
              </Text>
            </Block>
          ) : (
            <RoomImage
              borderRadius={999}
              room={room}
              width={120}
              height={120}
            />
          )}
        </Block>
        {!isDirect && canEditAvatar && (
          <Block
            flexDirection="row"
            align="center"
            gap={12}
            margins={{ marginBottom: 40 }}
          >
            <Button.Wrapper
              onPress={() => setIsListOpen(true)}
              disabled={isLoading || isSaving}
            >
              <Block
                flexDirection="row"
                align="center"
                gap={12}
                paddings={[16, 12]}
              >
                <Image
                  source={require("assets/icons/upload-simple-large.png")}
                  width={16}
                  height={16}
                  style={styles.icon}
                  tintColor={Colors.primary}
                />
                <Text size={TextSize.small} color={Colors.primary}>
                  Upload
                </Text>
              </Block>
            </Button.Wrapper>
            <Button.Wrapper
              onPress={handleRemove}
              disabled={isRemoveDisabled()}
            >
              <Block
                flexDirection="row"
                align="center"
                gap={12}
                paddings={[16, 12]}
              >
                <Image
                  source={require("assets/icons/trash.png")}
                  width={16}
                  height={16}
                  style={styles.icon}
                />
                <Text size={TextSize.small}>Remove</Text>
              </Block>
            </Button.Wrapper>
          </Block>
        )}
      </Block>
      <Block gap={20}>
        <Block gap={8}>
          <Text size={TextSize.tiny} color={Colors.white50} paddings={[0, 16]}>
            Display name
          </Text>
          <Input
            placeholder="Display name"
            value={displayName}
            disabled={isDirect || !canEditName}
            onChangeText={(value) => setDisplayName(value)}
          />
        </Block>
        <Block gap={8}>
          <Text size={TextSize.tiny} color={Colors.white50} paddings={[0, 16]}>
            Topic
          </Text>
          <Input
            placeholder="Add a topic"
            value={topic}
            disabled={!canEditTopic}
            onChangeText={(value) => setTopic(value)}
          />
        </Block>
      </Block>
      <Modal
        visible={isListOpen}
        transparent={true}
        presentationStyle="overFullScreen"
        animationType="fade"
      >
        <Block
          width="100%"
          height="100%"
          justify="flex-end"
